 economia:{name:'Economía naviera',teacher:'Buglioni',icon:'◇',color:'#8a4c68',sidebar:'#432737',ink:'#513244',muted:'#87717d',paper:'#f8f1f4',soft:'#f0e0e7',lime:'#efbad2',folder:'1Si9Eg-tmSnwyUOXV2GNzWM3HuFiN3VGR',description:'Mercados, transporte marítimo, cargas, fletamentos, compraventa y medios de pago.',detail:'Temario de práctica organizado a partir de los materiales de Economía Naviera.'},
