 electrotecnia:{name:'Electrotecnia',teacher:'Morales',icon:'ϟ',color:'#82651d',sidebar:'#3d341e',ink:'#494024',muted:'#80765b',paper:'#f8f5eb',soft:'#f0e8cd',lime:'#eedc83',folder:'1qtwx5gDgIJig5_APNn4PeEOeDRIxKzMB',description:'Corriente alterna, transformadores e interpretación de circuitos eléctricos.',detail:'Programa, actividades, preguntas de repaso y modelo de final.'},
