registerWorkshopSubjects(navalSubjects);
window.currentSubject='termicas';
try{const requested=new URLSearchParams(location.search).get('materia');currentSubject=requested&&navalSubjects[requested]?requested:localStorage.getItem('naval-subject-v1')||'termicas'}catch{}
if(!navalSubjects[currentSubject])currentSubject='termicas';
window.studyKeyFor=(userId,subject=currentSubject)=>'naval-study-v1'+(userId?':'+userId:'')+(subject==='termicas'?'':':materia:'+subject);
function readSubjectNotes(){window.localStudyKey=studyKeyFor(window.maqAccount?.user?.id);try{saved={done:[],notes:{},answers:{},...JSON.parse(localStorage.getItem(localStudyKey)||'{}')}}catch{saved={done:[],notes:{},answers:{}}}}
function syncSubjectLock(){const select=document.querySelector('#subject-select');if(select){const busy=typeof exam!=='undefined'&&(exam.busy||exam.recording);select.disabled=busy;select.title=busy?'Terminá de enviar o grabar la respuesta para cambiar de materia.':'Cambiar materia'}}
function syncSubjectChrome(){const s=navalSubjects[currentSubject],thermal=currentSubject==='termicas';document.documentElement.dataset.subject=currentSubject;for(const [key,value]of Object.entries({'--green':s.color,'--ink':s.ink,'--muted':s.muted,'--paper':s.paper,'--lime':s.lime,'--subject-sidebar':s.sidebar,'--subject-soft':s.soft}))document.documentElement.style.setProperty(key,value);document.querySelector('#subject-select').value=currentSubject;document.body.classList.toggle('workshop-pending',!!s.underConstruction);document.querySelector('#subject-teacher').textContent=s.underConstruction?'Taller · En construcción':'Docente · '+s.teacher;document.querySelector('.course').innerHTML='<small>Escuela Nacional Fluvial · 2.º año</small>';document.querySelector('.brand-icon').textContent=s.icon;document.querySelector('header>span').textContent='ESTUDIO / '+s.name.toLocaleUpperCase('es-AR');document.querySelector('.brand').href=thermal?'#taller':'#inicio';document.title=s.name+' · Cuaderno naval';for(const a of document.querySelectorAll('nav a'))if(['#taller','#esquemas'].includes(a.hash))a.hidden=!thermal;document.querySelector('#subject-home-nav').hidden=thermal;document.querySelector('#topics').hidden=false;document.querySelector('footer').textContent=thermal?'Modelos conceptuales para estudiar relaciones entre componentes; sin escala ni validez constructiva. Notas guardadas en este navegador; resultados del profesor guardados en tu cuenta.':'Materiales originales de '+s.name+' en Google Drive. Notas guardadas por materia y cuenta en este navegador.';if(s.underConstruction)document.querySelector('footer').textContent='Taller en construcción · Material de estudio pendiente de incorporar.';syncSubjectLock()}
function changeSubject(id){if(!navalSubjects[id]||id===currentSubject)return;window.cleanupExam?.();clearInterval(timerInterval);window.stopModel?.();currentSubject=id;try{localStorage.setItem('naval-subject-v1',id)}catch{}readSubjectNotes();window.configurePracticeSubject?.();const url=new URL(location.href);url.searchParams.set('materia',id);const route=location.hash.slice(1);url.hash=['biblioteca','notas','programa','cuenta','usuarios','oral'].includes(route)?route:id==='termicas'?'taller':'inicio';history.replaceState(null,'',url);document.querySelector('#unit-dialog')?.close();syncSubjectChrome();render()}
function subjectFiles(){return (courseMaterials[currentSubject]||[]).filter(f=>!/^download.*\.htm$/i.test(f.title)&&!f.title.endsWith('.xlsx')).slice().sort((a,b)=>Number(b.folder)-Number(a.folder)||a.title.localeCompare(b.title,'es',{numeric:true}))}
function subjectLink(f){return `<a class="subject-resource" href="${esc(f.url)}" target="_blank" rel="noopener"><span class="resource-symbol" aria-hidden="true">${f.folder?'▤':'↗'}</span><div><strong>${esc(f.title)}</strong><small>${f.folder?'Carpeta de materiales':'Archivo original en Google Drive'}</small></div><span aria-hidden="true">↗</span></a>`}
function renderSubject(route){const s=navalSubjects[currentSubject],files=subjectFiles();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));if(route==='profesor'){renderProfessor();return}if(route==='progreso'){renderProgressPage();return}if(route==='oral'){renderSubjectReview();return}document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route||a.hash==='#inicio'&&!['biblioteca','notas','programa','oral','profesor','progreso'].includes(route)));if(route==='notas'){app.innerHTML=head('CUADERNO · '+s.name,'Tus notas de '+s.name+'.','Un espacio propio para ordenar conceptos, dudas y preguntas de esta materia.')+`<section class="subject-notes"><label for="subject-note">Notas de ${esc(s.name)}</label><textarea id="subject-note" placeholder="¿Qué entendí? ¿Qué necesito repasar?" aria-label="Notas de ${esc(s.name)}">${esc(saved.notes.materia||'')}</textarea><p id="subject-save" class="save-status" role="status"></p><button id="subject-export" class="secondary">Descargar mis notas</button><p class="source">Guardado en este dispositivo y navegador, separado por cuenta y materia.</p></section>`;document.querySelector('#subject-note').oninput=e=>{saved.notes.materia=e.target.value;document.querySelector('#subject-save').textContent=persist()?'Notas guardadas en '+s.name+'.':'No se pudo guardar. Descargá una copia.'};document.querySelector('#subject-export').onclick=()=>{const url=URL.createObjectURL(new Blob([s.name+' · Mis notas\n\n'+(saved.notes.materia||'')],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='notas-'+currentSubject+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};return}
 if(route==='biblioteca'||route==='programa'){const program=route==='programa',selected=program?files.filter(f=>/programa|planificaci[oó]n/i.test(f.title)):files;app.innerHTML=head(s.name,program?'Programa y planificación.':'La biblioteca de '+s.name+'.',program?'Documentos identificados en la carpeta compartida; conservan el nombre y la fecha del original.':'Apuntes, guías y recursos de la materia. Los enlaces abren los originales y pueden requerir tu cuenta de Google.')+`<div class="subject-library-toolbar"><a class="button secondary" target="_blank" rel="noopener" href="https://drive.google.com/drive/folders/${s.folder}">Abrir carpeta completa ↗</a>${!program?'<label class="subject-search"><span>Buscar material</span><input id="subject-search" type="search" placeholder="Buscar por nombre…"></label>':''}</div>${program?subjectTopicCards():''}<div id="subject-resources">${selected.length?selected.map(subjectLink).join(''):'<div class="subject-empty">No hay un archivo identificado como programa en este índice. Consultá la carpeta original de la materia.</div>'}</div>`;const search=document.querySelector('#subject-search');if(search)search.oninput=e=>{const q=e.target.value.toLocaleLowerCase('es-AR');const matches=files.filter(f=>f.title.toLocaleLowerCase('es-AR').includes(q));document.querySelector('#subject-resources').innerHTML=matches.length?matches.map(subjectLink).join(''):'<p class="subject-empty">No hay coincidencias.</p>'};return}
 const programs=files.filter(f=>/programa|planificaci[oó]n/i.test(f.title));const featured=files.filter(f=>f.folder||/unidad|repaso|final|diagrama|circuito|transformador/i.test(f.title)).slice(0,6);app.innerHTML=`<section class="subject-hero"><div><span class="eyebrow">CUADERNO NAVAL · ${esc(s.teacher)}</span><h1>${esc(s.name)}.</h1><p class="lead">${esc(s.description)}</p><p class="subject-detail">${esc(s.detail)}</p><div class="actions"><a class="button" href="#oral">Empezar el repaso guiado →</a><a class="button secondary" href="#profesor">Practicar el oral</a><a class="button secondary" href="#biblioteca">Explorar materiales</a><a class="button secondary" href="#notas">Abrir mis notas</a></div></div><div class="subject-seal" aria-hidden="true"><span>${s.icon}</span><small>ESCUELA NACIONAL FLUVIAL<br>CUADERNO DE ESTUDIO · 2026</small></div></section><div class="subject-overview"><span><strong>${coursePractice[currentSubject]?.totalQuestions||0}</strong> preguntas preparadas</span><span><strong>${files.length}</strong> recursos y carpetas en el índice</span><span><strong>${programs.length}</strong> documentos de programa o planificación</span><span>Materia seleccionada · <b>${esc(s.name)}</b></span></div><div class="section-head"><h2>Para empezar.</h2><a href="#biblioteca">Ver todos los materiales ↗</a></div><div class="subject-featured">${featured.map(subjectLink).join('')}</div><div class="subject-bottom"><div><strong>Todo tiene su lugar.</strong><p>Los materiales y las notas pertenecen a ${esc(s.name)}. Podés volver a cambiar de materia desde el selector.</p></div><a target="_blank" rel="noopener" href="https://drive.google.com/drive/folders/${s.folder}">Carpeta original ↗</a></div>`}
document.querySelector('#subject-select').innerHTML=Object.entries(navalSubjects).map(([id,s])=>`<option value="${id}">${s.name}</option>`).join('');document.querySelector('#subject-select').onchange=e=>changeSubject(e.target.value);readSubjectNotes();syncSubjectChrome();
